  }
  const sources = choose('source', state.sources.map(item => [item.id, item.title + ' · ' +
    item.createdAt.slice(0, 19) + (item.withdrawal ? ' · withdrawn' : '')]), refreshSource ?? state.sources.at(-1).id);
